18	/**
19	 * 授权域服务：实现授权、写入、撤回与查询的业务规则及幂等语义。
20	 *
21	 * <p>幂等规则：成功结果与业务变更同事务保存；同一 requestId 相同参数重试返回原结果，
22	 * 参数变更返回 409；失败请求不占用 requestId。写入重放不得绕过授权状态：
23	 * 即使 requestId 命中幂等记录，只要所属代次已撤回，仍返回 410。
24	 */
25	@Service
26	public class ConsentService {
27	
28	    static final String CODE_GRANT_NOT_FOUND = "GRANT_NOT_FOUND";
29	    static final String CODE_RECORD_NOT_FOUND = "RECORD_NOT_FOUND";
30	    static final String CODE_REQUEST_ID_CONFLICT = "REQUEST_ID_CONFLICT";
31	    static final String CODE_RECORD_PAYLOAD_CONFLICT = "RECORD_PAYLOAD_CONFLICT";
32	    static final String CODE_GRANT_ALREADY_REVOKED = "GRANT_ALREADY_REVOKED";
33	    static final String CODE_CONSENT_REVOKED = "CONSENT_REVOKED";
34	
35	    private static final String OP_GRANT = "GRANT";
36	    private static final String OP_WRITE = "WRITE";
37	    private static final String OP_REVOKE = "REVOKE";
38	
39	    private final ConsentRepository consentRepository;
40	    private final IdempotencyRepository idempotencyRepository;
41	    private final ObjectMapper objectMapper;
42	
43	    public ConsentService(ConsentRepository consentRepository,
44	                          IdempotencyRepository idempotencyRepository,
45	                          ObjectMapper objectMapper) {
46	        this.consentRepository = consentRepository;
47	        this.idempotencyRepository = idempotencyRepository;
48	        this.objectMapper = objectMapper;
49	    }
