    private PurposeExport toPurposeExport(PurposeRow purposeRow, boolean withCurrentStatus) {
        String status = ExportResponse.STATUS_CURRENT;
        if (withCurrentStatus) {
            Optional<GrantRow> latest = consentRepository.findLatestGrant(
                    purposeRow.exportKey() == null ? null : findSubjectKey(purposeRow.exportKey()),
                    purposeRow.purpose());
