        return exportRepository.findSnapshot(exportKey)
                .map(SnapshotRow::subjectKey)
                .orElseThrow(() -> ApiException.notFound(CODE_EXPORT_NOT_FOUND, "导出快照不存在"));
    }

    /**
     * 幂等重放检查：命中且参数一致返回原快照；参数不一致返回 409。
